english:
import assert from "node:assert/strict";
import { JouzuUpdater, relaunchUpdatedJouzu } from ${moduleUrl("updater.js")};
import { loadMetadata } from ${moduleUrl("metadata.js")};
import { resolveJouzuPaths } from ${moduleUrl("paths.js")};
const executable = ${JSON.stringify(join(packageRoot, "dist", "cli.js"))};
const updater = new JouzuUpdater({
  paths: resolveJouzuPaths(),
  currentVersion: loadMetadata().jouzuVersion,
  executable,
  report: (message) => console.log(message),
});
const result = updater.startup();
assert.equal(result.action, "restart", JSON.stringify(result));
assert.equal(result.version, ${JSON.stringify(nextVersion)});
process.exitCode = relaunchUpdatedJouzu({ executable, args: ["--version"] });

${JSON.stringify(
				{
					providers: {
						loopback: {
							baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
							api: "openai-completions",
							apiKey: "loopback",
							compat: { supportsDeveloperRole: false, supportsReasoningEffort: false },
							models: [
								{
									id: "loopback-model",
									name: "Loopback",
									reasoning: false,
									input: ["text"],
									contextWindow: 8192,
									maxTokens: 512,
									cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
								},
							],
						},
					},
				},
				null,
				2,
			)}\n

import assert from "node:assert/strict";
				import { NativeTextGuard } from ${JSON.stringify(nativeModule)};
				const scanner = new NativeTextGuard();
				try {
					assert.equal((await scanner.scan("日本語の資料を確認します。")).status, "clear");
					assert.match(scanner.identity, /^[a-f0-9]{64}$/);
					const flagged = await scanner.scan("packed\\u202econtent");
					assert.equal(flagged.status, "findings");
					assert.ok(flagged.severityCounts.error > 0);
					assert.equal((await scanner.scan("after findings")).status, "clear");
				} finally { await scanner.close(); }
				assert.equal((await scanner.scan("closed")).reason, "closed");

export default function (pi) {
			pi.registerCommand("jouzu-surface-probe", {
				handler: async () => {
					const tools = pi.getAllTools().map((tool) => tool.name).sort();
					const commands = pi.getCommands().map((command) => command.name).sort();
					process.stderr.write("JOUZU_SURFACE_PROBE=" + JSON.stringify({ tools, commands, userInputAdapter: typeof pi.registerUserInputAdapter }) + "\\n");
				},
			});
		}

export default function (pi) {
			pi.registerTool({
				name: "vcc_recall",
				label: "duplicate",
				description: "duplicate",
				parameters: { type: "object", properties: {} },
				async execute() { return { content: [{ type: "text", text: "duplicate" }], details: {} }; },
			});
		}

export default function (pi) {
			pi.registerCommand("packed-user-fixture", { handler: async () => {} });
		}

